import{z as A,x as p,o as t,c as d,q as l,j as n,D as s,d as r,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Saga","description":"","frontmatter":{"title":"Saga","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/saga-pattern.md","filePath":"cs/saga-pattern.md","lastUpdated":1791413859000}'),B={name:"cs/saga-pattern.md"};function C(g,a,T,m,D,_){const E=p("Mermaid");return t(),d("div",null,[a[2]||(a[2]=l('<h1 id="saga" tabindex="-1">Saga <a class="header-anchor" href="#saga" aria-label="Permalink to &quot;Saga&quot;">​</a></h1><div class="epigraph"><p>长事务拆成一串本地事务，每步有补偿。不阻塞资源到结束，也不给全局原子：中间状态可见，补偿可能失败。</p><footer>—— 据 Garcia-Molina and Salem, Sagas, SIGMOD 1987 整理</footer></div><p>上一课<a href="/cs/idempotency-keys">幂等键</a>盖住单步骤重试。缺口是<strong>跨服务的一长串写</strong>：2PC 会把锁或连接占太久，且协调者脆。<a href="/cs/consensus-vs-2pc">共识与 2PC</a>已说明阻塞。Saga 用补偿换非阻塞，规格弱于原子提交。后课日志是实现编排的一种总线，不是 Saga 理论本身。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Garcia-Molina–Salem：saga = \\(T_1 C_1 T_2 C_2 \\ldots T_n\\)，每个 \\(T_i\\) 是本地事务，\\(C_i\\) 补偿 \\(T_i\\)。正向全成或补偿已执行前缀。隔离：saga 之间可以看见彼此的中间 \\(T_i\\)——这是相对 ACID 长事务的故意放松。</p><p>缺口：补偿不是回滚日志自动生成。订票补偿是退票，可能退不了，要人工。补偿也要幂等。编排（中心状态机）与协同（各步发事件）是实现拓扑。</p><p><span class="marginnote">1987 论文在单库长事务语境；微服务把它搬到跨进程。规格没变：可见中间态 + 补偿。</span></p><p><span class="marginnote">「补偿」不是回滚：回滚把数据库恢复到事务前的精确状态，补偿是再执行一个反向业务动作——订了票就退票，扣了款就退款。退票窗口、手续费、汇率变化都可能让「反向」不等于「复原」，这就是补偿可能失败、需要人工的根源。</span></p><p><span class="marginnote">直觉类比：Saga 像一串已经按下的开关——每按一个就立刻生效、别人看得见。走错到第 3 步才发现，只能按顺序再拨回去 3 次，而不是时间倒流到出发前。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每步：本地事务 + 幂等键 + 写「saga 日志」（自身 RSM 或 DB 行）标记进度。失败：对已完成前缀逆序 \\(C_i\\)。\\(C_i\\) 失败：重试或进死信，saga 停在部分补偿——这是规格允许的坑，必须可观测。</p>',11)),(t(),n(o,null,{default:s(()=>[i(E,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20T1%5B%22T1%22%5D%20--%3E%20T2%5B%22T2%22%5D%0A%20%20T2%20--%3E%20T3%5B%22T3%22%5D%0A%20%20T2%20-.-%3E%20C2%5B%22C2%22%5D%0A%20%20T1%20-.-%3E%20C1%5B%22C1%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"不要用 Saga 实现转账的强不变式「永不丢钱」而不另加账本对账：中间与补偿窗口里钱在路上。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"与 2PC：2PC 准备态对外不可见（理想）；Saga 的 \\(T_i\\) 已提交，对外可见。与 RSM：可用状态机编排 saga，每转换一条日志，崩溃可恢复——恢复的是编排状态，不是把 \\(T_i\\) 变未提交。",-1)),a[6]||(a[6]=e("p",null,"本课不把 BPMN 引擎当定理。也不写限价簿成交链。",-1)),a[7]||(a[7]=e("p",null,"并发：两个 saga 改同一账户，补偿与正向交错，需要业务层锁或版本，否则补偿打到别人的后续写上。这是 1987 已点的隔离弱点。",-1)),a[8]||(a[8]=e("p",null,[e("span",{class:"marginnote"},"数字实例：saga A 扣款 100 后，saga B 又扣 50，账户剩 -150 的待补状态；若 A 的补偿「加回 100」按余额字段整值改写而不按增量，B 的 50 就可能被覆盖吃掉。补偿要么用增量运算，要么带版本号条件更新——这正是「业务层锁或版本」的具体形态。")],-1)),(t(),n(o,null,{default:s(()=>[i(E,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20T3%5B%22T3%20%E6%89%A7%E8%A1%8C%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20LOG%5B%22%E5%86%99%20saga%20%E6%97%A5%E5%BF%97%3A%20%E8%BF%9B%E5%85%A5%E8%A1%A5%E5%81%BF%E9%98%B6%E6%AE%B5%22%5D%0A%20%20LOG%20--%3E%20ORDER%7B%22%E6%8C%89%E4%BB%80%E4%B9%88%E9%A1%BA%E5%BA%8F%E8%A1%A5%E5%81%BF%3F%22%7D%0A%20%20ORDER%20--%20%22%E9%80%86%E5%BA%8F%E5%89%8D%E7%BC%80%22%20--%3E%20C2%5B%22%E5%85%88%E6%89%A7%E8%A1%8C%20C2%22%5D%0A%20%20C2%20--%3E%20C2OK%7B%22C2%20%E6%88%90%E5%8A%9F%3F%22%7D%0A%20%20C2OK%20--%20%22%E6%88%90%E5%8A%9F%22%20--%3E%20C1%5B%22%E6%89%A7%E8%A1%8C%20C1%22%5D%0A%20%20C2OK%20--%20%22%E5%A4%B1%E8%B4%A5%22%20--%3E%20RETRY%7B%22%E5%8F%AF%E9%87%8D%E8%AF%95%3F%22%7D%0A%20%20RETRY%20--%20%22%E5%8F%AF%22%20--%3E%20C2%0A%20%20RETRY%20--%20%22%E4%B8%8D%E5%8F%AF%22%20--%3E%20DLQ%5B%22%E8%BF%9B%E6%AD%BB%E4%BF%A1%2C%20%E5%81%9C%E5%9C%A8%E9%83%A8%E5%88%86%E8%A1%A5%E5%81%BF%22%5D%0A%20%20C1%20--%3E%20C1OK%7B%22C1%20%E6%88%90%E5%8A%9F%3F%22%7D%0A%20%20C1OK%20--%20%22%E6%88%90%E5%8A%9F%22%20--%3E%20DONE%5B%22saga%20%E7%BB%93%E6%9D%9F(%E5%B7%B2%E8%A1%A5%E5%81%BF)%22%5D%0A%20%20C1OK%20--%20%22%E5%A4%B1%E8%B4%A5%22%20--%3E%20DLQ%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=l('<p>这张图回答的问题是：正向链在中间一步断掉之后，编排器接着走哪条路——按逆序逐个补偿、失败后重试还是进死信，以及为什么必须允许 saga 「停在部分补偿」这个可观测的中间态。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列补偿模式目录（retry、cancel、undo）。不引入 TCC 的 Try-Confirm 作为新理论，只点名它更接近 2PC 的资源预留。后课默认：跨服务长流程用 Saga 则接受中间可见与补偿失败路径；要原子用短 2PC 或单 RSM。Kafka 下一课提供事件序，不自动给补偿。</p><p>放松隔离是为了不阻塞。买回来的是运维与对账义务。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Saga：本地事务序列 + 补偿；中间态可见。</li><li>补偿必须幂等且可观测失败。</li><li>不替代 2PC 的原子；不替代幂等键的单步去重。</li><li>出处：Garcia-Molina and Salem, SIGMOD 1987。</li></ul>',6))])}const f=A(B,[["render",C]]);export{u as __pageData,f as default};
